PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?director ?deathDate
WHERE {
  VALUES ?film { dbr:Notes_on_the_Port_of_St._Francis dbr:De_Luxe_Annie }

  # director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER (BOUND(?director))

  # death date of the director (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?director dbo:deathDate ?dboDeath . }

  BIND (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
}
LIMIT 100

